# Code Generated by Sidekick is for learning and experimentation purposes only. Filename: test_qualitative.py
from agents.qualitative import run


def main():
    query = input("Ask a question: ").strip()

    if not query:
        print("Please enter a question.")
        return

    try:
        result = run(query)

        print("\nANSWER:")
        print(result["answer"])

        print("\nRETRIEVED SOURCES:")
        for chunk in result["chunks"]:
            print(f"- {chunk['source']} (chunk {chunk['chunk']})")

        print(f"\nInput tokens: {result['input_tokens']}")
        print(f"Output tokens: {result['output_tokens']}")

    except Exception as error:
        print(f"\nTest failed: {error}")


if __name__ == "__main__":
    main()
